import logging
import os
import signal
import threading
from typing import Optional, TYPE_CHECKING

from .utils import open_file
from . import portable_tray_actions as portable_actions
from . import tray_i18n
from .platform import permissions, icons, console

try:
    import pystray
    from PIL import Image
    TRAY_AVAILABLE = True
except ImportError:
    TRAY_AVAILABLE = False
    pystray = None
    Image = None

if TYPE_CHECKING:
    from .state_manager import StateManager
    from .config_manager import ConfigManager

STATUS_LABELS = {
    "idle": "Готов",
    "recording": "Запись",
    "processing": "Загрузка",
    "initializing": "Загрузка",
    "unavailable": "Ошибка",
}
STATUS_TITLES = {state: f"EXPC-WLK — {label}" for state, label in STATUS_LABELS.items()}
_startup_icon = None


def show_startup_status(state="initializing"):
    """UI only: show loading/error while the normal application initializes."""
    global _startup_icon
    if not TRAY_AVAILABLE:
        return
    try:
        image = icons.get_tray_icons()[state]
        language = tray_i18n.startup_language()
        title = "EXPC-WLK — " + tray_i18n.text(state, language)
        if _startup_icon is None:
            _startup_icon = pystray.Icon("whisper-key", image, title)
            _startup_icon.run_detached()
        else:
            _startup_icon.icon = image
            _startup_icon.title = title
    except Exception:
        logging.getLogger(__name__).warning("Startup status icon unavailable", exc_info=True)


def close_startup_status():
    global _startup_icon
    if _startup_icon is not None:
        try:
            _startup_icon.stop()
        except Exception:
            logging.getLogger(__name__).warning("Startup status cleanup failed", exc_info=True)
        finally:
            _startup_icon = None


class _StatusErrors(logging.Handler):
    def __init__(self, tray):
        super().__init__(logging.ERROR)
        self.tray = tray

    def emit(self, record):
        if record.name in (
            "whisper_key.whisper_engine", "whisper_key.audio_recorder",
            "whisper_key.state_manager", "whisper_key.hotkey_listener",
        ):
            self.tray._status_error = True


class SystemTray:
    def __init__(self,
                 state_manager: 'StateManager',
                 tray_config: dict = None,
                 config_manager: Optional['ConfigManager'] = None,
                 model_registry = None,
                 console_config: dict = None):

        self.state_manager = state_manager
        self.tray_config = tray_config or {}
        self.config_manager = config_manager
        self.model_registry = model_registry
        self.console_config = console_config or {}
        self.language = tray_i18n.resolve_language(self.tray_config.get("language"))
        self._update_lock = threading.Lock()
        self.logger = logging.getLogger(__name__)
               
        self.icon = None  # pystray object, holds menu, state, etc.
        self.is_running = False
        self.current_state = "initializing"
        self.hotkey_listener = None
        self._requested_state = "initializing"
        self._status_error = False
        self._autostart_display = None
        self._status_stop = threading.Event()
        self._error_handler = _StatusErrors(self)
        self.available = True
        
        if self._check_tray_availability():
            self._load_icons_to_cache()
    
    def _check_tray_availability(self) -> bool:
        if not self.tray_config['enabled']:
            self.logger.warning("   ✗ System tray disabled in configuration")
            self.available = False

        elif not TRAY_AVAILABLE:
            self.logger.warning("   ✗ System tray not available - pystray or Pillow not installed")
            self.available = False

        return self.available

    def _load_icons_to_cache(self):
        try:
            self.icons = icons.get_tray_icons()
        except Exception as e:
            self.logger.error(f"Failed to load tray icons: {e}")
            self.icons = {
                "idle": self._create_fallback_icon("idle"),
                "recording": self._create_fallback_icon("recording"),
                "processing": self._create_fallback_icon("processing"),
                "initializing": self._create_fallback_icon("initializing"),
                "unavailable": self._create_fallback_icon("unavailable"),
            }
        
    def _create_fallback_icon(self, state: str) -> Image.Image:
        colors = {
            "idle": (40, 190, 80),
            "recording": (235, 55, 55),
            "processing": (245, 195, 35),
            "initializing": (245, 195, 35),
            "unavailable": (140, 140, 140),
        }

        color = colors.get(state, (128, 128, 128))  # Default to gray
        icon = Image.new('RGBA', (16, 16), color + (255,))

        return icon
    
    def _build_model_menu_items(self, current_model: str, is_model_loading: bool) -> list:
        items = []

        if not self.model_registry:
            return items

        def make_model_selector(model_key):
            return lambda icon, item: self._select_model(model_key)

        def make_is_current(model_key):
            return lambda item: model_key == current_model

        def model_selection_enabled(item):
            return not is_model_loading

        first_group = True
        for group in self.model_registry.get_groups_ordered():
            models = self.model_registry.get_models_by_group(group)
            if not models:
                continue

            if not first_group:
                items.append(pystray.Menu.SEPARATOR)
            first_group = False

            for model in models:
                items.append(pystray.MenuItem(
                    model.label,
                    make_model_selector(model.key),
                    radio=True,
                    checked=make_is_current(model.key),
                    enabled=model_selection_enabled
                ))

        return items

    def _create_menu(self):
        try:
            app_state = self.state_manager.get_application_state()
            is_model_loading = app_state.get('model_loading', False)

            auto_paste_enabled = self.config_manager.get_setting('clipboard', 'auto_paste')
            current_model = self.config_manager.get_setting('whisper', 'model')

            available_hosts = self.state_manager.get_available_audio_hosts()
            current_host = self.state_manager.get_current_audio_host()

            def is_current_host(host_name):
                return lambda item: current_host == host_name

            def switch_host(host_name):
                return lambda icon, item: self._select_audio_host(host_name)

            audio_host_items = []
            if available_hosts:
                for host in available_hosts:
                    host_name = host['name']
                    audio_host_items.append(
                        pystray.MenuItem(
                            host_name,
                            switch_host(host_name),
                            radio=True,
                            checked=is_current_host(host_name)
                        )
                    )

            available_devices = self.state_manager.get_available_audio_devices(current_host)
            current_device = self.state_manager.get_current_audio_device_id()

            def is_current_device(dev_id):
                return lambda item: current_device == dev_id

            def switch_device(dev_id, dev_name):
                return lambda icon, item: self._select_audio_device(dev_id, dev_name)

            audio_device_items = []

            if available_devices:
                for device in available_devices:
                    device_id = device['id']
                    device_name = device['name']

                    audio_device_items.append(
                        pystray.MenuItem(
                            device_name,
                            switch_device(device_id, device['name']),
                            radio=True,
                            checked=is_current_device(device_id)
                        )
                    )

            model_sub_menu_items = self._build_model_menu_items(current_model, is_model_loading)

            voice_commands_enabled = self.config_manager.get_setting('voice_commands', 'enabled')

            menu_items = [
                pystray.MenuItem(lambda item: self._text("status") + ": " + self._text(self.current_state),
                                 None, enabled=False),
                pystray.MenuItem(lambda item: self._text("backend") + ": " + self._backend_label(),
                                 None, enabled=False),
                pystray.MenuItem(self._text("autostart"), self._toggle_autostart,
                                 checked=lambda item: self._autostart_checked()),
                pystray.MenuItem(self._text("restart"), self._restart_application),
                pystray.MenuItem(self._text("folder"), self._open_application_folder),
                pystray.MenuItem(self._text("updates"), self._check_updates),
                pystray.MenuItem(self._text("language"), pystray.Menu(
                    pystray.MenuItem("Русский", lambda icon, item: self._set_language("ru"),
                                     checked=lambda item: self.language == "ru", radio=True),
                    pystray.MenuItem("English", lambda icon, item: self._set_language("en"),
                                     checked=lambda item: self.language == "en", radio=True),
                )),
                pystray.Menu.SEPARATOR,
            ]

            if console.owns_console():
                menu_items.append(pystray.MenuItem(self._text("console"), self._show_console, default=True))
                menu_items.append(pystray.Menu.SEPARATOR)

            menu_items += [
                pystray.MenuItem(self._text("log"), self._open_log_file),
                pystray.MenuItem(self._text("cache"), self._open_model_cache),
                pystray.Menu.SEPARATOR,
                pystray.MenuItem(self._text("config_folder"), self._open_config_folder),
                pystray.MenuItem(self._text("settings"), self._open_config_file),
                pystray.MenuItem(self._text("commands"), self._open_commands_file) if voice_commands_enabled else None,
                pystray.Menu.SEPARATOR,
                pystray.MenuItem(
                    self._text("audio_host"),
                    pystray.Menu(*audio_host_items)
                ) if audio_host_items else None,
                pystray.MenuItem(
                    self._text("audio_source"),
                    pystray.Menu(*audio_device_items)
                ),
                pystray.Menu.SEPARATOR,
                pystray.MenuItem(self._text("paste"), lambda icon, item: self._set_transcription_mode(True), radio=True, checked=lambda item: auto_paste_enabled),
                pystray.MenuItem(self._text("copy"), lambda icon, item: self._set_transcription_mode(False), radio=True, checked=lambda item: not auto_paste_enabled),
                pystray.Menu.SEPARATOR,
                pystray.MenuItem(f"{self._text('model')}: {current_model.title()}", pystray.Menu(*model_sub_menu_items)),
            ]

            menu_items.extend([
                pystray.Menu.SEPARATOR,
                pystray.MenuItem(self._text("exit"), self._quit_application_from_tray)
            ])

            menu = pystray.Menu(*[item for item in menu_items if item is not None])

            return menu 
                
        except Exception as e:
            self.logger.error(f"Error in _create_menu: {e}")
            raise

    def _open_config_folder(self, icon=None, item=None):
        try:
            config_dir = os.path.dirname(self.config_manager.user_settings_path)
            open_file(config_dir)
        except Exception as e:
            self.logger.error(f"Failed to open config folder: {e}")

    def _open_config_file(self, icon=None, item=None):
        try:
            open_file(self.config_manager.user_settings_path)
        except Exception as e:
            self.logger.error(f"Failed to open config file: {e}")

    def _open_commands_file(self, icon=None, item=None):
        try:
            commands_path = os.path.join(
                os.path.dirname(self.config_manager.user_settings_path),
                "commands.yaml"
            )
            open_file(commands_path)
        except Exception as e:
            self.logger.error(f"Failed to open commands file: {e}")

    def _open_log_file(self, icon=None, item=None):
        try:
            log_path = self.config_manager.get_log_file_path()
            open_file(log_path)
        except Exception as e:
            self.logger.error(f"Failed to open log file: {e}")

    def _open_model_cache(self, icon=None, item=None):
        try:
            cache_path = self.model_registry.get_hf_cache_path()
            os.makedirs(cache_path, exist_ok=True)
            open_file(cache_path)
        except Exception as e:
            self.logger.error(f"Failed to open model cache: {e}")

    def _set_transcription_mode(self, auto_paste: bool):
        if auto_paste:
            if not permissions.check_accessibility_permission():
                if not permissions.handle_missing_permission(self.config_manager):
                    return
                auto_paste = False

        self.state_manager.update_transcription_mode(auto_paste)
        self.icon.menu = self._create_menu()

    def _select_model(self, model_key: str):
        try:
            success = self.state_manager.request_model_change(model_key)

            if success:
                self.config_manager.update_user_setting('whisper', 'model', model_key)
                self.icon.menu = self._create_menu()
            else:
                self.logger.warning(f"Request to change model to {model_key} was not accepted")

        except Exception as e:
            self.logger.error(f"Error selecting model {model_key}: {e}")

    def _select_audio_host(self, host_name: str):
        try:
            success = self.state_manager.set_audio_host(host_name)
            if success:
                self.icon.menu = self._create_menu()
            else:
                self.logger.warning(f"Request to change audio host to {host_name} was not accepted")
        except Exception as e:
            self.logger.error(f"Error selecting audio host {host_name}: {e}")

    def _select_audio_device(self, device_id: int, device_name: str):
        success = self.state_manager.request_audio_device_change(device_id, device_name)

        if success:
            self.config_manager.update_user_setting('audio', 'input_device', device_id)
            self.icon.menu = self._create_menu()
        else:
            self.logger.warning(f"Request to change audio device to {device_id} was not accepted")

    def _show_console(self, icon=None, item=None):
        console.show()

    def apply_console_settings(self):
        if not console.owns_console() or not self.available:
            return
        if self.console_config.get('start_hidden', False):
            console.hide()
        console.start_minimize_monitor(console.hide)

    def _text(self, key):
        return tray_i18n.text(key, self.language)

    def _title(self, state):
        return "EXPC-WLK — " + self._text(state) + " — " + self._backend_label()

    def _backend_label(self):
        engine = getattr(self.state_manager, "whisper_engine", None)
        if engine is not None and getattr(engine, "device", None) == "cuda":
            return "NVIDIA CUDA (FP16)"
        return "CPU (INT8)"

    def _set_language(self, language):
        try:
            tray_i18n.save_language(self.config_manager, language)
            self.language = language
            if self.icon:
                self.icon.title = self._title(self.current_state)
            self.refresh_menu()
        except Exception as error:
            self._action_error(error)

    def _check_updates(self, icon=None, item=None):
        if not self._update_lock.acquire(blocking=False):
            return
        def worker():
            try:
                from . import portable_updater
                result = portable_updater.check_latest()
                if self.icon:
                    self.icon.notify(self._text(result["status"]).format(**result), "EXPC-WLK")
                if result["status"] == "available":
                    portable_updater.offer_update(result, self.language, self._quit_application_from_tray)
            except Exception:
                self.logger.warning("Manual update check failed", exc_info=True)
                if self.icon:
                    self.icon.notify(self._text("update_failed"), "EXPC-WLK")
            finally:
                self._update_lock.release()
        threading.Thread(target=worker, daemon=True, name="manual-update").start()

    def _autostart_checked(self):
        try:
            return portable_actions.autostart_enabled()
        except OSError:
            return False

    def _action_error(self, error):
        import ctypes
        self.logger.warning("Portable tray action failed: %s", error)
        ctypes.windll.user32.MessageBoxW(None, str(error), "EXPC-WLK", 0x10)

    def _toggle_autostart(self, icon=None, item=None):
        try:
            portable_actions.set_autostart(not portable_actions.autostart_enabled())
        except OSError as error:
            self._action_error(error)
        finally:
            self.refresh_menu()

    def _restart_application(self, icon=None, item=None):
        try:
            portable_actions.request_restart()
        except Exception as error:
            self._action_error(error)
            return
        self._quit_application_from_tray()

    def _open_application_folder(self, icon=None, item=None):
        try:
            open_file(str(portable_actions.launcher_path().parent))
        except OSError as error:
            self._action_error(error)

    def _quit_application_from_tray(self, icon=None, item=None):        
        os.kill(os.getpid(), signal.SIGINT)
    
    def _display_state(self, requested):
        engine = self.state_manager.whisper_engine
        if self._status_error:
            return "unavailable"
        if self.state_manager.is_model_loading or engine.is_loading():
            return "initializing"
        if engine.model is None or not getattr(self.hotkey_listener, "is_listening", False):
            return "unavailable"
        return requested if requested in STATUS_TITLES else "unavailable"

    def _watch_status(self):
        while not self._status_stop.wait(0.2):
            try:
                self.update_state(self.state_manager.get_current_state())
                enabled = self._autostart_checked()
                if enabled != self._autostart_display:
                    self._autostart_display = enabled
                    self.refresh_menu()
            except Exception:
                self._status_error = True
                if self.icon:
                    self.icon.icon = self.icons["unavailable"]
                    self.icon.title = self._title("unavailable")

    def update_state(self, new_state: str):
        if not TRAY_AVAILABLE or not self.is_running:
            return
        if new_state in ("recording", "model_loading") and self._requested_state != new_state:
            self._status_error = False
        self._requested_state = new_state
        display = self._display_state(new_state)
        if display == self.current_state:
            return
        self.current_state = display
        try:
            self.icon.icon = self.icons[display]
            self.icon.title = self._title(display)
            self.icon.menu = self._create_menu()
        except Exception as e:
            self.logger.error(f"Failed to update tray icon: {e}")

    def refresh_menu(self):
        if not self.icon:
            return

        try:
            self.icon.menu = self._create_menu()
        except Exception as e:
            self.logger.error(f"Failed to refresh tray menu: {e}")
    
    def start(self):
        global _startup_icon
        if not self.available:
            return False

        if self.is_running:
            self.logger.warning("System tray is already running")
            return True

        try:
            display = self._display_state(self.state_manager.get_current_state())
            menu = self._create_menu()
            if _startup_icon is not None:
                self.icon = _startup_icon
                _startup_icon = None
                self.icon.icon = self.icons[display]
                self.icon.title = self._title(display)
                self.icon.menu = menu
            else:
                self.icon = pystray.Icon(
                    name="whisper-key", icon=self.icons[display],
                    title=self._title(display), menu=menu,
                )
                self.icon.run_detached()
            self.current_state = display
            self.is_running = True
            self._status_stop.clear()
            logging.getLogger().addHandler(self._error_handler)
            threading.Thread(target=self._watch_status, daemon=True, name="tray-status").start()
            from .portable_updater import mark_ready
            mark_ready()
            if self.config_manager and self.config_manager.config.get('_cpu_fallback'):
                self.icon.notify(self._text("cpu_fallback"), "EXPC-WLK")
            print("   ✓ System tray icon is running...")

            return True

        except Exception as e:
            self.logger.error(f"Failed to start system tray: {e}")
            return False
    
    def stop(self):
        self._status_stop.set()
        logging.getLogger().removeHandler(self._error_handler)
        if not self.is_running:
            return

        try:
            self.icon.stop()
            self.is_running = False

        except Exception as e:
            self.logger.error(f"Error stopping system tray: {e}")
